import{F as e}from"./chunks/FigureContainer.VL3Ntwlh.js";import{H as i}from"./chunks/HighLightText.D0qzB827.js";import{c as p,o as g,a as n,b as o,d as s,e as l,w as r}from"./chunks/vitepress-theme-teek.VWKGyrHm.js";/* empty css                                                                               *//* empty css                                                             */const P=JSON.parse('{"title":"从“复合型人才”到“系统架构师”：AI 原生时代个人能力的进化指南","description":"探讨 AI 原生时代个人能力的升维路径：提问力进化为系统编排、品味封装为验收标准、智力诚实验证回路化、指数增长基础设施化，最终从复合型人才进化为系统架构师。","frontmatter":{"title":"从“复合型人才”到“系统架构师”：AI 原生时代个人能力的进化指南","tldr":"将提问力与品味封装为可执行的 Agent 与 Skill 系统，让个人能力从脑内判断进化为持续运转的自动化飞轮。","description":"探讨 AI 原生时代个人能力的升维路径：提问力进化为系统编排、品味封装为验收标准、智力诚实验证回路化、指数增长基础设施化，最终从复合型人才进化为系统架构师。","tags":["composite-talent","system-architect","agent-skill"],"categories":["产品 Sense","新 T 型人"],"date":"2026-07-16T20:21:38.000Z","sticky":1,"top":true,"coverImg":"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/cover/product-sense-articles/person_to_arc_engineering.png","permalink":"/product-sense/ai-to-system-architect-guide"},"headers":[],"relativePath":"product-sense/ai-to-system-architect-guide.md","filePath":"10.产品 Sense/02.新 T 型人/22.从“复合型人才”到“系统架构师”.md"}'),a={name:"product-sense/ai-to-system-architect-guide.md"},T=Object.assign(a,{setup(d){return(A,t)=>(g(),p("div",null,[t[23]||(t[23]=n("h1",{id:"从-复合型人才-到-系统架构师-ai-原生时代个人能力的进化指南",tabindex:"-1"},[l("从“复合型人才”到“系统架构师”：AI 原生时代个人能力的进化指南 "),n("a",{class:"header-anchor",href:"#从-复合型人才-到-系统架构师-ai-原生时代个人能力的进化指南","aria-label":"Permalink to “从“复合型人才”到“系统架构师”：AI 原生时代个人能力的进化指南”"},"​")],-1)),t[24]||(t[24]=n("blockquote",null,[n("p",null,[n("strong",null,"摘要"),l(": 基于 2024 年旧文《AI 原生时代的复合型人才》与 2026 年 AI 行业半年观察，重新审视复合型人才五大核心特质的升维路径。当 AI 从聊天框走向 Agent、Skill 与 Harness 三层架构，提问力不再是对话框中的一行字而是系统编排的起点，品味从脑中直觉外化为可执行验收标准，智力诚实从内心独白进化为写进门禁的验证回路，指数增长从依赖个人意志变为持续运转的能力飞轮，好奇心则成为连接线下真实世界的锚点。文章最终指出，AI 原生时代对人才的要求已从“很会想”的独思者转向“很会搭”的系统架构师，而关键动作在于将个人判断标准封装为可复用 Skill、将长期目标拆解为 Agent 循环、并在 AI 输出处永远多问一句“这真的够好吗”。")])],-1)),o(e,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/cover/product-sense-articles/person_to_arc_engineering.png",caption:""}),t[25]||(t[25]=s('<h2 id="_1-时隔两年-底层特质未变-载体却已升维" tabindex="-1">1. 时隔两年，底层特质未变，载体却已升维 <a class="header-anchor" href="#_1-时隔两年-底层特质未变-载体却已升维" aria-label="Permalink to “1. 时隔两年，底层特质未变，载体却已升维”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">核心要点</p><p>AI 原生时代对人才的要求，已从 <strong>“很会想”</strong> 的独思者，转向 <strong>“很会搭”</strong> 的 <strong>系统架构师</strong>。</p><ul><li>提问力→系统编排</li><li>品位→Skill 资产</li><li>智力诚实→验证回路</li></ul></div><p>2024 年 6 月，我写过一篇<a href="/product-sense/ai-native-composite-talents">读后感：AI 原生时代的复合型人才，究竟需要怎样的特质？</a>，谈保罗·格雷厄姆（Paul Graham）的《How to Do Great Work》与 AI 原生时代复合型人才的关系。那篇文章里，我总结了五个当时看来颇为前沿的判断：</p><ul><li>从“解决问题”到“发现问题”，提问力决定生产力；培养非共识的“品味”，才能逃离 AI 生成的“平均数”；</li><li>保持智力诚实与打破规则的勇气，以此抵抗 AI 的幻觉与平庸；</li><li>借助 AI 放大个人杠杆，实现复合指数增长；</li><li>在算力面前保持好奇——那是人类最后的底牌。</li></ul><p>文章写于 2024 年 AI 问答爆发的时候，当时我们还在把 AI 当作“超级解答机”来用。而在 2026 年过去的这半年里，我也在 AI industry 中观察到了一组更深刻的范式迁移：从聊天框里的对话，走向能读文件、调工具、跑检查的 Agent；从单点的 Prompt 技巧，走向可复用的 Skill 封装；从个人的提问能力，走向系统化的 Harness 搭建。</p>',5)),n("p",null,[t[1]||(t[1]=l("重新整理旧文，我最大的感触是：特质仍是底层操作系统，但上层应用已经天翻地覆。当 AI 从“超级解答机”进化成能读文件、调工具、跑检查的 Agent，复合型人才之间的区别，不再只是“你想得清不清”，而是 ",-1)),o(i,{type:"note",bold:""},{default:r(()=>[...t[0]||(t[0]=[l("“你能否把想得清的东西，变成 AI 可执行的系统”",-1)])]),_:1}),t[2]||(t[2]=l("。",-1))]),t[26]||(t[26]=s('<p>下面，我想借这半年多的观察，重新映射那五大特质在今天的落地形态。</p><h2 id="_2-提问力进化-从写好-prompt-到设计-loop" tabindex="-1">2. 提问力进化：从写好 Prompt 到设计 Loop <a class="header-anchor" href="#_2-提问力进化-从写好-prompt-到设计-loop" aria-label="Permalink to “2. 提问力进化：从写好 Prompt 到设计 Loop”">​</a></h2><p>回看 2024 年的旧文，我曾写道：PG 说“问题不仅导向答案，而且也导向更多的问题”，在 AI 时代，寻找答案的能力不再稀缺，稀缺的是提出绝佳问题的能力，而 Prompt 质量正是我们洞察力与品味的映射。</p><p>而在这半年多的观察里，这些观点找到了新的载体。</p><p>Greg Isenberg 把“搭 Agent”称为 <strong>Prompt Engineering 的成年版</strong>。在他看来，你不再只是给模型一句话然后等回答，而是要给 Agent 合适的上下文、接上工具、设好权限、让它记住必要信息，并知道何时该停下来检查自己。他建议的一个最小练习很接地气：做一个每日简报 Agent，读取三个信息源、看看日历、扫一遍笔记，先给你一版草稿，等你批准再发出去。</p><p>腾讯的 WorkBuddy 近期也成为国内日活很高的桌面 Agent，其核心逻辑正是把腾讯系能力（微云、问卷、地图、邮箱）Skill 化，让人用自然语言调度一整套系统。Decagon 的实践则更直白：企业先用昂贵的前沿模型验证场景，待输入分布明确后，再迁移到“小模型 + 深度微调”的开源权重——这背后，同样是<strong>定义问题边界再为边界选工具</strong>的能力。</p>',6)),n("p",null,[t[4]||(t[4]=l("我的新体会是：今天的“提问”，早已不是对话框里的一行字，而是一次系统编排。PG 说“问题导向更多问题”，现在你要建的是一个能持续产生子问题、自动执行、等待你验收的循环（Loop）。",-1)),o(i,{type:"note",bold:""},{default:r(()=>[...t[3]||(t[3]=[l("“初级用户写提示词，高级用户设计流程，真正的高手设计闭环系统”",-1)])]),_:1}),t[5]||(t[5]=l(" —— 这正是这半年多的观察中反复浮现的暗线。",-1))]),t[27]||(t[27]=n("p",null,[l("当你让 Codex、Claude Code 或 WorkBuddy 等 Agent 去做事时，你实际在回答：“任务从哪来？谁执行？怎么检查？失败怎么办？状态记在哪？”。能把这串答案写清楚的人，才真正拥有了"),n("strong",null,"进化版的提问力"),l("。")],-1)),t[28]||(t[28]=n("h2",{id:"_3-品味封装-从非共识判断到-skill-资产",tabindex:"-1"},[l("3. 品味封装：从非共识判断到 Skill 资产 "),n("a",{class:"header-anchor",href:"#_3-品味封装-从非共识判断到-skill-资产","aria-label":"Permalink to “3. 品味封装：从非共识判断到 Skill 资产”"},"​")],-1)),t[29]||(t[29]=n("div",{class:"tip custom-block"},[n("p",{class:"custom-block-title"},"Paul Graham"),n("p",null,[n("strong",null,"除非我们知道什么是最好的，以及是什么使它成为最好的，否则我们不知道自己在追求什么。")])],-1)),t[30]||(t[30]=n("p",null,"旧文里我引用 PG 的话：“除非我们知道什么是最好的，以及是什么使它成为最好的，否则我们不知道自己在追求什么。”当时我感叹，AI 正在批量生产无差别的“及格线以上”内容，品味成了把稳方向盘的核心资产。",-1)),n("p",null,[t[7]||(t[7]=l("但真正的变化在于：",-1)),o(i,{type:"note",bold:""},{default:r(()=>[...t[6]||(t[6]=[l("品味不再只是脑中的直觉判断，而正在被翻译成可执行的标准",-1)])]),_:1}),t[8]||(t[8]=l("。它从“把稳方向盘”的个人修为，变成了能让 Agent 千万次执行的系统输入。",-1))]),t[31]||(t[31]=s("<p>我们在借助 Codex、Claude Code 等 Agent 构建知识库、学习系统、产品时，正在践行如何把“品味”封装成可执行的标准。比如：</p><p><strong>学习方法 Skill 化：</strong> 把学习方法翻译成可执行任务，比如将费曼学习法翻译成“理解这个概念”，而是让学习者完成一组动作——用自己的话解释、找出含糊表达、补一个案例、再重新解释一次。</p><p><strong>知识库 Skill 化：</strong> 把知识库构建与管理，借助卡片笔记法、Wiki 等方法论封装一套 Skills，比如“每张卡片限一个概念、必须双向链接、每周 review 孤儿卡片、每月导出知识图谱”，让知识库从静态文档变成 <strong>可执行的知识资产</strong>。</p><p><strong>产品设计 Skill 化：</strong> 把产品设计翻译成可执行任务，比如将一个需求翻译成“质量标准：需求清晰、边界明确、可开发、可测试；失败处理：信息不足先提问”的 Skill，或者将一个功能翻译成“需求收集→方案设计→原型评审→开发验收”的 Loop。</p><p>Skill 比提示词稳定，比 Agent 简单，是 <strong>能力资产的中间层</strong>。当然，Skill 也慢慢有了同质化风险：当所有团队用同一套 Skill 做前端设计，产品会看起来一样。好的 Skill 应只解决一个明确问题，带清晰的退出条件。</p>",5)),n("p",null,[t[10]||(t[10]=l("我的新体会是：过去我说“品味无法靠算法习得”，这话仍对。但今天，我们可以把个人的非共识品味，外化为 Skill 里的验收标准。比如你判断一个 PRD 够不够优雅，不该只存于脑中，而应写成 SKILL.md 里的 ",-1)),o(i,{type:"note",bold:""},{default:r(()=>[...t[9]||(t[9]=[l("“质量标准：需求清晰、边界明确、可开发、可测试；失败处理：信息不足先提问”",-1)])]),_:1}),t[11]||(t[11]=l("。",-1))]),t[32]||(t[32]=n("p",null,"这正是复合型人才与纯技术执行者的分野。很多主流 Agent 应用产品能生成内容、可视化图片、UI，甚至是生产级代码。但若没有人的品味注入 Skill，输出大概率是平均值的变体。",-1)),o(i,{type:"note",bold:""},{default:r(()=>[...t[12]||(t[12]=[l("复合型人才的新分工，是做那个定义“什么算好”的人，然后让 Agent 按此标准千万次执行。",-1)])]),_:1}),t[33]||(t[33]=l("。",-1)),t[34]||(t[34]=n("h2",{id:"_4-智力诚实工程化-从敢于说-不-到验证回路",tabindex:"-1"},[l("4. 智力诚实工程化：从敢于说“不”到验证回路 "),n("a",{class:"header-anchor",href:"#_4-智力诚实工程化-从敢于说-不-到验证回路","aria-label":"Permalink to “4. 智力诚实工程化：从敢于说“不”到验证回路”"},"​")],-1)),t[35]||(t[35]=n("p",null,"PG 在原文中强调，要抓住不合理的迹象，真正伟大的创新往往是对常识的颠覆。我在旧文里写到：复合型人才要对 AI 看似完美的常规解答说“不，这里还有缺陷”。",-1)),t[36]||(t[36]=n("p",null,[l("而今天，这种“说不”的勇气，已经可以被工程化——从个人面对AI答案时的主观判断，变成一套"),n("strong",null,"可执行、可量化、可复现的验证回路"),l("。")],-1)),t[37]||(t[37]=n("p",null,[l("比如，一个错误不能只记“我错了”，而要包含错误是什么、当时如何理解、根本原因、复测时间，并引入外部验证机制——用脚本检查目录完整、任务含验收、错误有复测，绝不单靠 AI 自评。这种"),n("strong",null,"结构化的反馈回路"),l("，把模糊的“我觉得不对”变成了可追溯的验证标准。")],-1)),t[38]||(t[38]=n("p",null,"也有很多团队坦诚，开箱即用的通用模型达不到高质量场景的要求，必须针对特定任务深度微调。先用能力更强的模型摸清失败模式，成熟后再迁移到轻量模型——这本身就是一种智力诚实：承认通用智能在已知点上的浪费，承认我们还没完全理解问题。",-1)),n("p",null,[t[14]||(t[14]=l("Greg 的每日简报 Agent 标准很接地气：",-1)),o(i,{type:"note",bold:""},{default:r(()=>[...t[13]||(t[13]=[l("“有没有省下十分钟？有没有抓到你漏掉的信息？产出能不能直接用？”",-1)])]),_:1}),t[15]||(t[15]=l("——他把诚实变成了可量化的 eval。",-1))]),t[39]||(t[39]=s('<p>所谓智力诚实，不再只是内心独白，而是<strong>写进门禁与契约</strong>。你把“说不”的权利，提前编码进了每一个自动化检查节点——结构化反馈、模型选型策略、量化验证标准，最终都指向同一个目标：当 AI 给出标准答案，你按下暂停键的动作，不再是临时起意，而是预设的验证机制。</p><h2 id="_5-复合指数增长-从周末-mvp-到个人能力基础设施" tabindex="-1">5. 复合指数增长：从周末 MVP 到个人能力基础设施 <a class="header-anchor" href="#_5-复合指数增长-从周末-mvp-到个人能力基础设施" aria-label="Permalink to “5. 复合指数增长：从周末 MVP 到个人能力基础设施”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">指数增长的问题在于曲线在开始时给人的感觉很平，但它不是。</p><p>PG 在旧文中指出：杰出成就的累积效应是被严重低估的，关键在于一致性。同时，我们不需要做庞大的计划，只需要做“<strong>可能有用的最简单的东西”</strong>，并在实践中不断演化。</p></div><p>我的新体会是：以项目为单位的拖延在进一步变得不可承受——因为你能把项目拆成 Agent 循环，让它在你睡觉时跑。<strong>执行引擎可以脱离人体独立运转</strong>，目标写入仓库、任务被执行、错误被记录、路线根据反馈调整，整个循环不再像之前那样依赖人的持续在场。</p><p>这带来了三层变化：</p><ul><li>增长从一次性项目变成持续运转的基础设施——你不再做“30天计划”，而是搭建“能力飞轮”：先做最小项目验证想法，再啃真实案例打磨技能，接着封装成可复用的 Skill，然后构建自动执行的 Agent，最后沉淀出作品集形成复利。</li><li>产品与分发在同一个人手中形成闭环——用最短循环做出最小产品，同时做多个分发动作，<strong>让市场反馈直接驱动下一轮迭代</strong>。</li><li>学习与工程实践不再是线性的积累，而是<strong>渐进式的能力基础设施搭建</strong>——每一次成功或失败，都变成系统的一部分，让下一轮运行更精准。</li></ul><p>指数增长的关键不再是意志，而是<strong>系统持续运行</strong>。你只需保证目标写入仓库、任务被执行、错误被记录、路线根据反馈调。AI 负责低价值整理，你负责高价值决策。这正是 PG 所说“做可能有用的最简单的东西，并在实践中演化”的自动化版本。</p><h2 id="_6-好奇心与线下-不可压缩的人类底盘" tabindex="-1">6. 好奇心与线下：不可压缩的人类底盘 <a class="header-anchor" href="#_6-好奇心与线下-不可压缩的人类底盘" aria-label="Permalink to “6. 好奇心与线下：不可压缩的人类底盘”">​</a></h2><p>之前我把好奇心称为人类最后的底牌：AI 不会为一个微小不合理现象抓狂，也不会为未知答案彻夜难眠。</p>',9)),n("p",null,[t[17]||(t[17]=l("我现在的新体会是：工作越多转移给 Agent，真实世界里的关系反而越有分量。当机器能处理大部分信息和执行，那些无法被数字化的东西——",-1)),o(i,{type:"note",bold:""},{default:r(()=>[...t[16]||(t[16]=[l("眼神交流中的犹豫、面对面讨论时突然迸发的灵感、建立在长期共处上的信任",-1)])]),_:1}),t[18]||(t[18]=l("——成了真正的稀缺资源。哪怕是最智能的产品，最终仍要回到人的原生场景中，因为社交与信任无法被算法完全替代。",-1))]),n("p",null,[t[20]||(t[20]=l("更重要的是，当 Agent 接手执行，你省下的时间",-1)),t[21]||(t[21]=n("strong",null,"不该填回更多任务",-1)),t[22]||(t[22]=l("——那只会加剧倦怠。真正的答案是：",-1)),o(i,{type:"note",bold:""},{default:r(()=>[...t[19]||(t[19]=[l("去追寻让你过分好奇的问题。那些让你深夜仍在思考、让你为一个不合理现象反复推敲的东西，才是驱动你不断进化的引擎。",-1)])]),_:1})]),t[40]||(t[40]=s('<p>线下社区、一对一信任、用身体在场的观察——这些<strong>原子世界的不确定性</strong>，是 AI 轻飘感的解药。复合型人才的最高级杠杆，是用 AI 放大好奇心，然后带人回到房间里确认：“这事咱们真要做吗？”</p><h2 id="_7-结语-别只收藏-去建造" tabindex="-1">7. 结语：别只收藏，去建造 <a class="header-anchor" href="#_7-结语-别只收藏-去建造" aria-label="Permalink to “7. 结语：别只收藏，去建造”">​</a></h2><p>两年前我写旧文，呼吁守住提问与品味。而今天，当 AI 从聊天框走向 Agent、从提示词走向 Skill、从单点执行走向系统闭环，五大特质的落地形态已经完成了一次升维：</p><ul><li>提问力不再是对话框里的一行字，而是系统编排的起点。</li><li>品味不再是脑中的直觉，而是可执行的验收标准。</li><li>智力诚实不再是内心独白，而是写进门禁的验证回路。</li><li>指数增长不再依赖个人意志，而是持续运转的能力飞轮。</li><li>好奇心不再只是个人特质，而是连接真实世界的锚点。</li></ul><p><strong>AI 原生时代的复合型人才，不再是“很会想”的独思者，而是“很会搭”的系统架构师。</strong></p><p>你想清了特质，下一步可以很轻：</p><p>从一个高频重复任务开始，把你的判断标准写成可执行的 Skill；把一个长期目标拆成 Agent 循环，让它在你睡觉时继续运转；在 AI 给你答案的地方，多问一句“这真的够好吗？”。然后，记得留出时间去线下——去聊那些让你好奇的问题，去建立那些无法被数字化的信任。</p><p>还有很多发现正等待着被发现。在 2026 年，我们不再是独自出发，为什么不由我们，带着一群 Agent 一起去发现呢？</p>',8))]))}});export{P as __pageData,T as default};
